from __future__ import annotations

from pathlib import Path


ENGINE = Path("modules/compounder_engine.py")
APP = Path("app.py")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f"Could not find expected block for {label}")
    return text.replace(old, new, 1)


def update_engine() -> None:
    text = ENGINE.read_text(encoding="utf-8")

    marker = '''\n\ndef _merge_pipeline(\n    quant_data: pd.DataFrame,\n    agent_data: pd.DataFrame,\n) -> pd.DataFrame:\n'''
    gate_code = '''\n\ndef _numeric(frame: pd.DataFrame, column: str) -> pd.Series:\n    if column not in frame.columns:\n        return pd.Series(np.nan, index=frame.index, dtype=float)\n    return pd.to_numeric(frame[column], errors="coerce")\n\n\ndef _text(frame: pd.DataFrame, column: str) -> pd.Series:\n    if column not in frame.columns:\n        return pd.Series("", index=frame.index, dtype=object)\n    return frame[column].fillna("").astype(str).str.strip()\n\n\ndef apply_promotion_gate(data: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Klassificér Emerging Compounders i en kontrolleret research-pipeline.\n\n    Promotion Gate er ikke et købssignal. Den afgør kun, hvor langt en kandidat\n    må bevæge sig i analyseflowet:\n\n    Monitor -> Deep Research -> Fair Value Review -> Decision Review.\n\n    Decision Review kræver dokumenteret valuation og risikogates. Først efter\n    separat Investment OS-analyse kan kandidaten blive en egentlig Opportunity.\n    \"\"\"\n    if data.empty:\n        return data.copy()\n\n    result = data.copy()\n\n    discovery = _numeric(result, "Discovery_Score")\n    confidence = _numeric(result, "Unified_Confidence")\n    quant_quality = _numeric(result, "Data_Quality")\n    agent_confidence = _numeric(result, "Agent_Confidence")\n\n    revenue_growth = _numeric(result, "Revenue_CAGR_5Y")\n    eps_growth = _numeric(result, "EPS_CAGR_5Y")\n    gross_margin = _numeric(result, "Gross_Margin")\n    growth_score = _numeric(result, "Growth_Score")\n    earnings_score = _numeric(result, "Earnings_Score")\n    moat_score = _numeric(result, "Moat_Score")\n\n    momentum_3m = _numeric(result, "Momentum_3M")\n    momentum_6m = _numeric(result, "Momentum_6M")\n    agent_momentum = _numeric(result, "Agent_Momentum_Score")\n\n    upside = _numeric(result, "Upside_Pct")\n    downside = _numeric(result, "Downside_Pct")\n    risk_reward = _numeric(result, "Risk_Reward")\n    quant_risk = _text(result, "Risk").str.lower()\n    agent_risk = _text(result, "Agent_Risk").str.lower()\n\n    # Deep Research skal være relativt åben: formålet er netop at udfylde\n    # manglende viden på lovende discovery-kandidater.\n    deep_research_ready = discovery.ge(75) & confidence.ge(70)\n\n    data_quality_ok = quant_quality.ge(60) | agent_confidence.ge(80)\n    growth_ok = revenue_growth.ge(0.10) | growth_score.ge(70)\n    earnings_ok = eps_growth.ge(0.12) | earnings_score.ge(70)\n    moat_ok = gross_margin.ge(0.40) | moat_score.ge(70)\n    risk_ok = ~quant_risk.eq("high") & ~agent_risk.eq("high")\n\n    fair_value_ready = (\n        discovery.ge(80)\n        & confidence.ge(75)\n        & data_quality_ok\n        & growth_ok\n        & earnings_ok\n        & moat_ok\n        & risk_ok\n    )\n\n    momentum_ok = (momentum_3m.gt(0) & momentum_6m.gt(0)) | agent_momentum.ge(70)\n    valuation_available = upside.notna() & risk_reward.notna()\n    valuation_ok = valuation_available & upside.ge(0.15) & risk_reward.ge(1.5)\n    downside_ok = downside.isna() | downside.gt(-0.35)\n\n    decision_review_ready = (\n        fair_value_ready\n        & discovery.ge(85)\n        & confidence.ge(80)\n        & momentum_ok\n        & valuation_ok\n        & downside_ok\n    )\n\n    result["Deep_Research_Ready"] = deep_research_ready\n    result["Fair_Value_Ready"] = fair_value_ready\n    result["Decision_Review_Ready"] = decision_review_ready\n\n    result["Promotion_Stage"] = np.select(\n        [decision_review_ready, fair_value_ready, deep_research_ready],\n        ["Decision Review", "Fair Value Review", "Deep Research"],\n        default="Monitor",\n    )\n    result["Next_Action"] = np.select(\n        [decision_review_ready, fair_value_ready, deep_research_ready],\n        [\n            "Send til Decision Review",\n            "Lav/validér fair value",\n            "Start dybdeanalyse",\n        ],\n        default="Overvåg",\n    )\n\n    reason_rows: list[str] = []\n    for idx in result.index:\n        reasons: list[str] = []\n        if bool(decision_review_ready.loc[idx]):\n            reasons.append("Discovery ≥85 og confidence ≥80")\n            reasons.append("Vækst, moat, momentum og risiko består")\n            reasons.append("Upside ≥15% og risk/reward ≥1,5")\n        elif bool(fair_value_ready.loc[idx]):\n            reasons.append("Kvalitet består Promotion Gate")\n            if not bool(valuation_available.loc[idx]):\n                reasons.append("Fair value mangler")\n            elif not bool(valuation_ok.loc[idx]):\n                reasons.append("Valuation består ikke gate")\n            elif not bool(momentum_ok.loc[idx]):\n                reasons.append("Momentum består ikke Decision Review-gate")\n            else:\n                reasons.append("Decision Score-gate endnu ikke opfyldt")\n        elif bool(deep_research_ready.loc[idx]):\n            reasons.append("Discovery ≥75 og confidence ≥70")\n            missing: list[str] = []\n            if not bool(data_quality_ok.loc[idx]):\n                missing.append("datakvalitet")\n            if not bool(growth_ok.loc[idx]):\n                missing.append("vækst")\n            if not bool(earnings_ok.loc[idx]):\n                missing.append("indtjening")\n            if not bool(moat_ok.loc[idx]):\n                missing.append("moat")\n            if not bool(risk_ok.loc[idx]):\n                missing.append("risiko")\n            if missing:\n                reasons.append("Mangler: " + ", ".join(missing))\n        else:\n            reasons.append("Discovery/confidence under Deep Research-gate")\n        reason_rows.append(" · ".join(reasons))\n\n    result["Promotion_Reasons"] = reason_rows\n    return result\n\n\ndef _merge_pipeline(\n    quant_data: pd.DataFrame,\n    agent_data: pd.DataFrame,\n) -> pd.DataFrame:\n'''
    text = replace_once(text, marker, gate_code, "promotion gate function")

    old = '''    result["Research_Priority"] = np.select(\n        [\n            result["Discovery_Score"].ge(85)\n            & result["Unified_Confidence"].ge(75),\n            result["Discovery_Score"].ge(75),\n        ],\n        ["Høj", "Middel"],\n        default="Monitor",\n    )\n\n    return result.sort_values(\n'''
    new = '''    result["Research_Priority"] = np.select(\n        [\n            result["Discovery_Score"].ge(85)\n            & result["Unified_Confidence"].ge(75),\n            result["Discovery_Score"].ge(75),\n        ],\n        ["Høj", "Middel"],\n        default="Monitor",\n    )\n\n    result = apply_promotion_gate(result)\n\n    return result.sort_values(\n'''
    text = replace_once(text, old, new, "apply promotion gate")

    old = '''        "Research_Priority",\n        "Pipeline_Source",\n        "Composite_Score",\n'''
    new = '''        "Research_Priority",\n        "Promotion_Stage",\n        "Next_Action",\n        "Promotion_Reasons",\n        "Deep_Research_Ready",\n        "Fair_Value_Ready",\n        "Decision_Review_Ready",\n        "Pipeline_Source",\n        "Composite_Score",\n'''
    text = replace_once(text, old, new, "top candidate promotion columns")

    old = '''            "New_Candidate_Count": 0,\n            "Agent_Generated_At": radar.agent_generated_at,\n        }\n'''
    new = '''            "New_Candidate_Count": 0,\n            "Deep_Research_Count": 0,\n            "Fair_Value_Count": 0,\n            "Decision_Review_Count": 0,\n            "Agent_Generated_At": radar.agent_generated_at,\n        }\n'''
    text = replace_once(text, old, new, "empty promotion summary")

    old = '''    new_count = int(data.get("Is_New", pd.Series(False, index=data.index)).fillna(False).sum())\n\n    top_candidate = data.iloc[0]["Name"] if not data.empty else None\n\n    return {\n        "Candidate_Count": int(len(data)),\n        "High_Confidence_Count": high_confidence,\n        "Average_Confidence": average_confidence,\n        "Top_Candidate": top_candidate,\n        "New_Candidate_Count": new_count,\n        "Agent_Generated_At": radar.agent_generated_at,\n    }\n'''
    new = '''    new_count = int(data.get("Is_New", pd.Series(False, index=data.index)).fillna(False).sum())\n    deep_count = int(\n        data.get("Deep_Research_Ready", pd.Series(False, index=data.index))\n        .fillna(False)\n        .sum()\n    )\n    fair_value_count = int(\n        data.get("Fair_Value_Ready", pd.Series(False, index=data.index))\n        .fillna(False)\n        .sum()\n    )\n    decision_review_count = int(\n        data.get("Decision_Review_Ready", pd.Series(False, index=data.index))\n        .fillna(False)\n        .sum()\n    )\n\n    top_candidate = data.iloc[0]["Name"] if not data.empty else None\n\n    return {\n        "Candidate_Count": int(len(data)),\n        "High_Confidence_Count": high_confidence,\n        "Average_Confidence": average_confidence,\n        "Top_Candidate": top_candidate,\n        "New_Candidate_Count": new_count,\n        "Deep_Research_Count": deep_count,\n        "Fair_Value_Count": fair_value_count,\n        "Decision_Review_Count": decision_review_count,\n        "Agent_Generated_At": radar.agent_generated_at,\n    }\n'''
    text = replace_once(text, old, new, "promotion summary counts")

    ENGINE.write_text(text, encoding="utf-8")


def update_app() -> None:
    text = APP.read_text(encoding="utf-8")
    text = text.replace('page_title="Investment OS 7.1"', 'page_title="Investment OS 7.2"', 1)
    text = text.replace('APP_VERSION = "7.1.0"', 'APP_VERSION = "7.2.0"', 1)
    text = text.replace('st.title("📈 Investment OS 7.1")', 'st.title("📈 Investment OS 7.2")', 1)

    old = '''    st.caption(\n        "7.1 kombinerer den mekaniske kvant-radar med mandags-agentens "\n        "intelligence-lag. Discovery Score er research-prioritering – ikke et købssignal."\n    )\n'''
    new = '''    st.caption(\n        "7.2 kombinerer kvant-radar og agent-intelligence med en Promotion Gate: "\n        "Monitor → Deep Research → Fair Value Review → Decision Review. "\n        "Discovery Score er stadig research-prioritering – ikke et købssignal."\n    )\n'''
    text = replace_once(text, old, new, "compounder caption")

    old = '''        c1, c2, c3, c4, c5 = st.columns(5)\n        c1.metric("Kandidater", compounder_summary["Candidate_Count"])\n        c2.metric("Nye", compounder_summary.get("New_Candidate_Count", 0))\n        c3.metric("Confidence ≥ 80%", compounder_summary["High_Confidence_Count"])\n        c4.metric(\n            "Gns. confidence",\n            (\n                f"{compounder_summary['Average_Confidence']:.0f}%"\n                if pd.notna(compounder_summary["Average_Confidence"]) else "N/A"\n            ),\n        )\n        c5.metric("Topkandidat", compounder_summary["Top_Candidate"] or "N/A")\n'''
    new = '''        c1, c2, c3, c4, c5, c6 = st.columns(6)\n        c1.metric("Kandidater", compounder_summary["Candidate_Count"])\n        c2.metric("Nye", compounder_summary.get("New_Candidate_Count", 0))\n        c3.metric("Deep Research", compounder_summary.get("Deep_Research_Count", 0))\n        c4.metric("Fair Value", compounder_summary.get("Fair_Value_Count", 0))\n        c5.metric("Decision Review", compounder_summary.get("Decision_Review_Count", 0))\n        c6.metric("Topkandidat", compounder_summary["Top_Candidate"] or "N/A")\n\n        st.caption(\n            "Promotion Gate kræver stigende evidens for hvert trin. Decision Review "\n            "kræver bl.a. valuation, momentum og risiko – og er stadig ikke en købsordre."\n        )\n'''
    text = replace_once(text, old, new, "compounder metrics")

    old = '''                "Research_Priority": "Research",\n                "Pipeline_Source": "Kilde",\n'''
    new = '''                "Research_Priority": "Research",\n                "Promotion_Stage": "Pipeline Stage",\n                "Next_Action": "Næste trin",\n                "Promotion_Reasons": "Gate-begrundelse",\n                "Pipeline_Source": "Kilde",\n'''
    text = replace_once(text, old, new, "compounder display columns")

    old = '''            st.dataframe(\n                table_style(radar), use_container_width=True,\n                hide_index=True, height=no_scroll_height(radar),\n            )\n\n\nwith tab_watchlist:\n'''
    new = '''            st.dataframe(\n                table_style(radar), use_container_width=True,\n                hide_index=True, height=no_scroll_height(radar),\n            )\n\n            st.markdown("### Promotion Queue")\n            st.caption(\n                "Kun kandidater, der består mindst Deep Research-gaten, vises her. "\n                "Decision Review-kandidater er klar til separat Investment OS-vurdering."\n            )\n            promotion_source = compounder_radar.data.copy()\n            promotion_queue = promotion_source.loc[\n                promotion_source.get(\n                    "Deep_Research_Ready", pd.Series(False, index=promotion_source.index)\n                ).fillna(False)\n            ].copy()\n            if promotion_queue.empty:\n                st.info("Ingen kandidater består aktuelt Promotion Gate til Deep Research.")\n            else:\n                stage_order = {\n                    "Decision Review": 0,\n                    "Fair Value Review": 1,\n                    "Deep Research": 2,\n                    "Monitor": 3,\n                }\n                promotion_queue["Stage_Order"] = (\n                    promotion_queue["Promotion_Stage"].map(stage_order).fillna(9)\n                )\n                promotion_queue = promotion_queue.sort_values(\n                    ["Stage_Order", "Discovery_Score", "Unified_Confidence"],\n                    ascending=[True, False, False],\n                    na_position="last",\n                )\n                promotion_display = promotion_queue[\n                    [\n                        "Name", "Ticker", "Promotion_Stage", "Next_Action",\n                        "Discovery_Score", "Unified_Confidence",\n                        "Promotion_Reasons",\n                    ]\n                ].head(12).copy()\n                promotion_display.columns = [\n                    "Selskab", "Ticker", "Pipeline Stage", "Næste trin",\n                    "Discovery", "Confidence", "Gate-begrundelse",\n                ]\n                for col in ["Discovery", "Confidence"]:\n                    promotion_display[col] = promotion_display[col].apply(\n                        lambda value: score_text(value, 0) if pd.notna(value) else "N/A"\n                    )\n                st.dataframe(\n                    table_style(promotion_display),\n                    use_container_width=True,\n                    hide_index=True,\n                    height=no_scroll_height(promotion_display),\n                )\n\n\nwith tab_watchlist:\n'''
    text = replace_once(text, old, new, "promotion queue UI")

    APP.write_text(text, encoding="utf-8")


def main() -> None:
    update_engine()
    update_app()
    print("Applied Investment OS 7.2 Compounder Promotion Gate")


if __name__ == "__main__":
    main()
